/**
 * @method
 * @name deribit#createOrder
 * @description create a trade order
 * @see https://docs.deribit.com/api-reference/trading/private-buy
 * @see https://docs.deribit.com/api-reference/trading/private-sell
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much you want to trade in units of the base currency. For perpetual and inverse futures the amount is in USD units. For options it is in the underlying assets base currency.
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.trigger] the trigger type 'index_price', 'mark_price', or 'last_price', default is 'last_price'
 * @param {float} [params.trailingAmount] the quote amount to trail away from the current market price
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Deribit) CreateOrderAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Deribit) createOrderBody(ch chan AsyncResult[Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"instrument_name": market["id"],
		"amount":          this.AmountToPrecision(symbol, amount),
		"type":            typeVar,
	}
	var trigger *string = this.SafeString(params, "trigger", "last_price")
	var timeInForce *string = this.SafeStringUpper(params, "timeInForce")
	var reduceOnly *bool = this.SafeBool2(params, "reduceOnly", "reduce_only")
	// only stop loss sell orders are allowed when price crossed from above
	var stopLossPrice *string = this.SafeString(params, "stopLossPrice")
	// only take profit buy orders are allowed when price crossed from below
	var takeProfitPrice *string = this.SafeString(params, "takeProfitPrice")
	var trailingAmount *string = this.SafeString2(params, "trailingAmount", "trigger_offset")
	var isTrailingAmountOrder bool = (trailingAmount != nil)
	var isStopLimit bool = (typeVar == "stop_limit")
	var isStopMarket bool = (typeVar == "stop_market")
	var isTakeLimit bool = (typeVar == "take_limit")
	var isTakeMarket bool = (typeVar == "take_market")
	var isStopLossOrder bool = isStopLimit || isStopMarket || (stopLossPrice != nil)
	var isTakeProfitOrder bool = isTakeLimit || isTakeMarket || (takeProfitPrice != nil)
	if isStopLossOrder && isTakeProfitOrder {
		panic(InvalidOrder(this.Id + " createOrder () only allows one of stopLossPrice or takeProfitPrice to be specified"))
	}
	var isStopOrder bool = isStopLossOrder || isTakeProfitOrder
	var isLimitOrder bool = (typeVar == "limit") || isStopLimit || isTakeLimit
	var isMarketOrder bool = (typeVar == "market") || isStopMarket || isTakeMarket
	var exchangeSpecificPostOnly any = this.SafeValue(params, "post_only")
	var postOnly bool = this.IsPostOnly(isMarketOrder, exchangeSpecificPostOnly, params)
	if isLimitOrder {
		request["type"] = "limit"
		request["price"] = this.PriceToPrecision(symbol, price)
	} else {
		request["type"] = "market"
	}
	if isTrailingAmountOrder {
		request["trigger"] = trigger
		request["type"] = "trailing_stop"
		request["trigger_offset"] = this.ParseToNumeric(trailingAmount)
	} else if isStopOrder {
		var triggerPrice *string = func() *string {
			if stopLossPrice != nil {
				return stopLossPrice
			}
			return takeProfitPrice
		}()
		request["trigger_price"] = this.PriceToPrecision(symbol, triggerPrice)
		request["trigger"] = trigger
		if isStopLossOrder {
			if isMarketOrder {
				// stop_market (sell only)
				request["type"] = "stop_market"
			} else {
				// stop_limit (sell only)
				request["type"] = "stop_limit"
			}
		} else {
			if isMarketOrder {
				// take_market (buy only)
				request["type"] = "take_market"
			} else {
				// take_limit (buy only)
				request["type"] = "take_limit"
			}
		}
	}
	if reduceOnly != nil && *reduceOnly == true {
		request["reduce_only"] = true
	}
	if postOnly {
		request["post_only"] = true
		request["reject_post_only"] = true
	}
	if timeInForce != nil {
		if timeInForce != nil && *timeInForce == "GTC" {
			request["time_in_force"] = "good_til_cancelled"
		}
		if timeInForce != nil && *timeInForce == "IOC" {
			request["time_in_force"] = "immediate_or_cancel"
		}
		if timeInForce != nil && *timeInForce == "FOK" {
			request["time_in_force"] = "fill_or_kill"
		}
	}
	var paramsOmitted map[string]any = this.OmitDict(params, []any{"timeInForce", "stopLossPrice", "takeProfitPrice", "postOnly", "reduceOnly", "trailingAmount"})
	var response map[string]any = nil
	if this.Capitalize(side) == "Buy" {

		r1 := <-this.PrivateGetBuy(this.Extend(request, paramsOmitted))
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Value
	} else {

		r2 := <-this.PrivateGetSell(this.Extend(request, paramsOmitted))
		if r2.Err != nil {
			panic(r2.Err)
		}
		response = r2.Value
	}
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "id": 5275,
	//         "result": {
	//             "trades": [
	//                 {
	//                     "trade_seq": 14151,
	//                     "trade_id": "ETH-37435",
	//                     "timestamp": 1550657341322,
	//                     "tick_direction": 2,
	//                     "state": "closed",
	//                     "self_trade": false,
	//                     "price": 143.81,
	//                     "order_type": "market",
	//                     "order_id": "ETH-349249",
	//                     "matching_id": null,
	//                     "liquidity": "T",
	//                     "label": "market0000234",
	//                     "instrument_name": "ETH-PERPETUAL",
	//                     "index_price": 143.73,
	//                     "fee_currency": "ETH",
	//                     "fee": 0.000139,
	//                     "direction": "buy",
	//                     "amount": 40
	//                 }
	//             ],
	//             "order": {
	//                 "time_in_force": "good_til_cancelled",
	//                 "reduce_only": false,
	//                 "profit_loss": 0,
	//                 "price": "market_price",
	//                 "post_only": false,
	//                 "order_type": "market",
	//                 "order_state": "filled",
	//                 "order_id": "ETH-349249",
	//                 "max_show": 40,
	//                 "last_update_timestamp": 1550657341322,
	//                 "label": "market0000234",
	//                 "is_liquidation": false,
	//                 "instrument_name": "ETH-PERPETUAL",
	//                 "filled_amount": 40,
	//                 "direction": "buy",
	//                 "creation_timestamp": 1550657341322,
	//                 "commission": 0.000139,
	//                 "average_price": 143.81,
	//                 "api": true,
	//                 "amount": 40
	//             }
	//         }
	//     }
	//
	var result map[string]any = SafeMapTyped(response, "result")
	var order map[string]any = this.Extend(this.SafeValue(result, "order"), map[string]any{
		"trades": this.SafeList(result, "trades", []any{}),
	})

	ch <- AsyncResult[Order]{Value: this.ParseOrder(order, market)}
	return nil
}

/**
 * @method
 * @name deribit#editOrder
 * @description edit a trade order
 * @see https://docs.deribit.com/api-reference/trading/private-edit
 * @param {string} id edit order id
 * @param {string} [symbol] unified symbol of the market to edit an order in
 * @param {string} [type] 'market' or 'limit'
 * @param {string} [side] 'buy' or 'sell'
 * @param {float} amount how much you want to trade in units of the base currency. For perpetual and inverse futures the amount is in USD units. For options it is in the underlying assets base currency.
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {float} [params.trailingAmount] the quote amount to trail away from the current market price
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Deribit) EditOrderAsync(id string, symbol any, typeVar any, side any, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.editOrderBody(ch, id, symbol, typeVar, side, optionalArgs...)
	return ch
}
func (this *Deribit) editOrderBody(ch chan AsyncResult[Order], id string, symbol any, typeVar any, side any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var amount *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = amount
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 1, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if amount == nil {
		panic(ArgumentsRequired(this.Id + " editOrder() requires an amount argument"))
	}
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var request map[string]any = map[string]any{
		"order_id": id,
		"amount":   this.AmountToPrecision(symbol, amount),
	}
	if price != nil {
		request["price"] = this.PriceToPrecision(symbol, price)
	}
	var trailingAmount *string = this.SafeString2(params, "trailingAmount", "trigger_offset")
	var isTrailingAmountOrder bool = (trailingAmount != nil)
	var paramsOmitted any = params
	if isTrailingAmountOrder {
		paramsOmitted = this.Omit(params, "trigger_offset")
	}
	if isTrailingAmountOrder {
		request["trigger_offset"] = this.ParseToNumeric(trailingAmount)
	}

	r1 := <-this.PrivateGetEdit(this.Extend(request, paramsOmitted))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	var result map[string]any = SafeMapTyped(response, "result")
	var order map[string]any = this.Extend(this.SafeValue(result, "order"), map[string]any{
		"trades": this.SafeList(result, "trades", []any{}),
	})

	ch <- AsyncResult[Order]{Value: this.ParseOrder(order)}
	return nil
}

