func (this *Deribit) fetchMyTradesBody(ch chan AsyncResult[[]Trade], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var request map[string]any = map[string]any{
		"include_old": true,
	}
	var market map[string]any = nil
	if limit != nil {
		request["count"] = limit // default 10
	}
	var response map[string]any = nil
	if symbol == nil {
		var code *string = this.CodeFromOptions("fetchMyTrades", params)
		var currency map[string]any = this.Currency(code)
		request["currency"] = currency["id"]
		if since == nil {

			r1 := <-this.PrivateGetGetUserTradesByCurrency(this.Extend(request, params))
			if r1.Err != nil {
				panic(r1.Err)
			}
			response = r1.Value
		} else {
			request["start_timestamp"] = since

			r2 := <-this.PrivateGetGetUserTradesByCurrencyAndTime(this.Extend(request, params))
			if r2.Err != nil {
				panic(r2.Err)
			}
			response = r2.Value
		}
	} else {
		market = this.Market(symbol)
		request["instrument_name"] = market["id"]
		if since == nil {

			r3 := <-this.PrivateGetGetUserTradesByInstrument(this.Extend(request, params))
			if r3.Err != nil {
				panic(r3.Err)
			}
			response = r3.Value
		} else {
			request["start_timestamp"] = since

			r4 := <-this.PrivateGetGetUserTradesByInstrumentAndTime(this.Extend(request, params))
			if r4.Err != nil {
				panic(r4.Err)
			}
			response = r4.Value
		}
	}
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "id": 9367,
	//         "result": {
	//             "trades": [
	//                 {
	//                     "trade_seq": 3,
	//                     "trade_id": "ETH-34066",
	//                     "timestamp": 1550219814585,
	//                     "tick_direction": 1,
	//                     "state": "open",
	//                     "self_trade": false,
	//                     "reduce_only": false,
	//                     "price": 0.04,
	//                     "post_only": false,
	//                     "order_type": "limit",
	//                     "order_id": "ETH-334607",
	//                     "matching_id": null,
	//                     "liquidity": "M",
	//                     "iv": 56.83,
	//                     "instrument_name": "ETH-22FEB19-120-C",
	//                     "index_price": 121.37,
	//                     "fee_currency": "ETH",
	//                     "fee": 0.0011,
	//                     "direction": "buy",
	//                     "amount": 11
	//                 },
	//             ],
	//             "has_more": true
	//         }
	//     }
	//
	var result map[string]any = SafeMapTyped(response, "result")
	var trades []any = SafeListTypedDefault(result, "trades", []any{})

	ch <- AsyncResult[[]Trade]{Value: TradesFromList(this.ParseTrades(trades, market, since, limit))}
	return nil
}

