/**
 * @method
 * @name deribit#fetchFundingRateHistory
 * @description fetch the current funding rate
 * @see https://docs.deribit.com/api-reference/market-data/public-get_funding_rate_history
 * @param {string} symbol unified market symbol
 * @param {int} [since] the earliest time in ms to fetch funding rate history for
 * @param {int} [limit] the maximum number of entries to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] fetch funding rate ending at this timestamp
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [availble parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
 * @returns {object} a [funding rate structure]{@link https://docs.ccxt.com/?id=funding-rate-structure}
 */
func (this *Deribit) FetchFundingRateHistoryAsync(optionalArgs ...any) <-chan AsyncResult[[]FundingRateHistory] {
	ch := make(chan AsyncResult[[]FundingRateHistory], 1)
	go this.fetchFundingRateHistoryBody(ch, optionalArgs...)
	return ch
}
func (this *Deribit) fetchFundingRateHistoryBody(ch chan AsyncResult[[]FundingRateHistory], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	paginate, paramsPaginate := this.HandleOptionBoolAndParams(params, "fetchFundingRateHistory", "paginate", false)
	var maxEntriesPerRequest int = 744 // seems exchange returns max 744 items per request
	var eachItemDuration string = "1h"
	if paginate {
		// fix for: https://github.com/ccxt/ccxt/issues/25040
		var paginationParams map[string]any = this.Extend(paramsPaginate, map[string]any{
			"isDeribitPaginationCall": true,
		})

		r1 := <-this.FetchPaginatedCallDeterministicAsync("fetchFundingRateHistory", symbol, since, limit, eachItemDuration, paginationParams, maxEntriesPerRequest)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var retRes332419 []any = r1.Value
		if retRes332419 == nil {
			ch <- AsyncResult[[]FundingRateHistory]{Value: nil}
		} else {
			ch <- AsyncResult[[]FundingRateHistory]{Value: FundingRateHistoriesFromList(retRes332419)}
		}
		return nil
	}
	var duration int64 = this.ParseTimeframe(eachItemDuration) * 1000
	var now int64 = this.Milliseconds()
	var month int64 = (30 * 24) * 60 * 60 * 1000
	var defaultSince int64 = now - month
	var sinceResolved int64 = func() int64 {
		if since == nil {
			return defaultSince
		}
		return *since
	}()
	var time int64 = now
	if since != nil {
		time = this.ParseToInt(*since + month)
	}
	var request map[string]any = map[string]any{
		"instrument_name": market["id"],
		"start_timestamp": (sinceResolved - 1),
	}
	var until *int64 = this.SafeInteger2(paramsPaginate, "until", "end_timestamp")
	var paramsUntil map[string]any = func() map[string]any {
		if until != nil {
			return this.OmitDict(paramsPaginate, []any{"until"})
		}
		return paramsPaginate
	}()
	var endTimestamp int64 = time
	if until != nil {
		endTimestamp = this.ParseToInt(until)
	}
	request["end_timestamp"] = endTimestamp
	var isPaginationCall *bool = this.SafeBool(paramsUntil, "isDeribitPaginationCall", false)
	var paramsOmitted any = paramsUntil
	if isPaginationCall != nil && *isPaginationCall {
		paramsOmitted = this.Omit(paramsUntil, "isDeribitPaginationCall")
	}
	if isPaginationCall != nil && *isPaginationCall {
		if limit == nil {
			panic(ArgumentsRequired(this.Id + " fetchFundingRateHistory() requires a limit argument"))
		}
		var maxUntil int64 = this.ParseToInt(this.Sum(sinceResolved, *limit*duration))
		request["end_timestamp"] = func() int64 {
			if endTimestamp < maxUntil {
				return endTimestamp
			}
			return maxUntil
		}()
	}

	r2 := <-this.PublicGetGetFundingRateHistory(this.Extend(request, paramsOmitted))
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response map[string]any = r2.Value
	//
	//    {
	//        "jsonrpc": "2.0",
	//        "id": 7617,
	//        "result": [
	//          {
	//            "timestamp": 1569891600000,
	//            "index_price": 8222.87,
	//            "prev_index_price": 8305.72,
	//            "interest_8h": -0.00009234260068476106,
	//            "interest_1h": -4.739622041017375e-7
	//          }
	//        ]
	//    }
	//
	var rates []any = []any{}
	var result []any = SafeListTyped(response, "result")
	for i := 0; i < len(result); i++ {
		var fr map[string]any = SafeMapTyped(result, i)
		var rate map[string]any = FundingRateToMap(this.ParseFundingRate(fr, market))
		rates = append(rates, rate)
	}

	ch <- AsyncResult[[]FundingRateHistory]{Value: FundingRateHistoriesFromList(this.FilterBySymbolSinceLimit(rates, symbol, sinceResolved, limit))}
	return nil
}
func (this *Deribit) ParseFundingRate(contract any, optionalArgs ...any) FundingRate {
	//
	//   {
	//       "jsonrpc":"2.0",
	//       "result":"0",
	//       "usIn":"1691161645596519",
	//       "usOut":"1691161645597149",
	//       "usDiff":"630",
	//       "testnet":false
	//   }
	// history
	//   {
	//     "timestamp": 1569891600000,
	//     "index_price": 8222.87,
	//     "prev_index_price": 8305.72,
	//     "interest_8h": -0.00009234260068476106,
	//     "interest_1h": -4.739622041017375e-7
	//   }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.SafeInteger(contract, "timestamp")
	var datetime *string = this.Iso8601(timestamp)
	var result *float64 = this.SafeNumber2(contract, "result", "interest_8h")
	return FundingRateFromMap(map[string]any{
		"info":                     contract,
		"symbol":                   this.SafeSymbol(nil, market),
		"markPrice":                nil,
		"indexPrice":               this.SafeNumber(contract, "index_price"),
		"interestRate":             nil,
		"estimatedSettlePrice":     nil,
		"timestamp":                timestamp,
		"datetime":                 datetime,
		"fundingRate":              result,
		"fundingTimestamp":         nil,
		"fundingDatetime":          nil,
		"nextFundingRate":          nil,
		"nextFundingTimestamp":     nil,
		"nextFundingDatetime":      nil,
		"previousFundingRate":      nil,
		"previousFundingTimestamp": nil,
		"previousFundingDatetime":  nil,
		"interval":                 "8h",
	})
}

/**
 * @method
 * @name deribit#fetchLiquidations
 * @description retrieves the public liquidations of a trading pair
 * @see https://docs.deribit.com/api-reference/market-data/public-get_last_settlements_by_currency
 * @param {string} symbol unified CCXT market symbol
 * @param {int} [since] the earliest time in ms to fetch liquidations for
 * @param {int} [limit] the maximum number of liquidation structures to retrieve
 * @param {object} [params] exchange specific parameters for the deribit api endpoint
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [availble parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
 * @returns {object} an array of [liquidation structures]{@link https://docs.ccxt.com/?id=liquidation-structure}
 */
func (this *Deribit) FetchLiquidationsAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[[]Liquidation] {
	ch := make(chan AsyncResult[[]Liquidation], 1)
	go this.fetchLiquidationsBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Deribit) fetchLiquidationsBody(ch chan AsyncResult[[]Liquidation], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var since *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	paginate, paramsPaginate := this.HandleOptionBoolAndParams(params, "fetchLiquidations", "paginate", false)
	if paginate {

		r1 := <-this.FetchPaginatedCallCursorAsync("fetchLiquidations", symbol, since, limit, paramsPaginate, "continuation", "continuation", nil)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var retRes344619 []any = r1.Value
		if retRes344619 == nil {
			ch <- AsyncResult[[]Liquidation]{Value: nil}
		} else {
			ch <- AsyncResult[[]Liquidation]{Value: LiquidationsFromList(retRes344619)}
		}
		return nil
	}
	var market map[string]any = this.Market(symbol)
	if market["spot"] == true {
		panic(NotSupported(this.Id + " fetchLiquidations() does not support " + *this.SafeString(market, "type", "") + " markets"))
	}
	var request map[string]any = map[string]any{
		"instrument_name": market["id"],
		"type":            "bankruptcy",
	}
	if since != nil {
		request["search_start_timestamp"] = since
	}
	if limit != nil {
		request["count"] = limit
	}

	r2 := <-this.PublicGetGetLastSettlementsByInstrument(this.Extend(request, paramsPaginate))
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response map[string]any = r2.Value
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "result": {
	//             "settlements": [
	//                 {
	//                     "type": "bankruptcy",
	//                     "timestamp": 1696579200041,
	//                     "funded": 10000.0,
	//                     "session_bankrupcy": 10000.0
	//                     "session_profit_loss": 112951.68715857354,
	//                     "session_tax": 0.15,
	//                     "session_tax_rate": 0.0015,
	//                     "socialized": 0.001,
	//                 },
	//             ],
	//             "continuation": "5dHzoGyD8Hs8KURoUhfgXgHpJTA5oyapoudSmNeAfEftqRbjNE6jNNUpo2oCu1khnZL9ao"
	//         },
	//         "usIn": 1696652052254890,
	//         "usOut": 1696652052255733,
	//         "usDiff": 843,
	//         "testnet": false
	//     }
	//
	var result map[string]any = SafeMapTyped(response, "result")
	var cursor *string = this.SafeString(result, "continuation")
	var settlements []any = SafeListTypedDefault(result, "settlements", []any{})
	var settlementsWithCursor any = this.AddPaginationCursorToResult(cursor, settlements)

	ch <- AsyncResult[[]Liquidation]{Value: LiquidationsFromList(this.ParseLiquidations(settlementsWithCursor, market, since, limit))}
	return nil
}
func (this *Deribit) AddPaginationCursorToResult(cursor *string, data []any) any {
	if cursor != nil {
		var dataLength int = len(data)
		if dataLength > 0 {
			var first map[string]any = this.SafeDictMap(data, 0, map[string]any{})
			var last map[string]any = this.SafeDictMap(data, dataLength-1, map[string]any{})
			first["continuation"] = *cursor
			last["continuation"] = *cursor
			AddElementToObject(data, 0, first)
			AddElementToObject(data, dataLength-1, last)
		}
	}
	return data
}

